import{c as o,Q as t,j as d,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Instruction Files 全量自我稽核（CLAUDE.md / rules / refs / skills / agents / memory）","description":"","frontmatter":{"title":"Instruction Files 全量自我稽核（CLAUDE.md / rules / refs / skills / agents / memory）","date":"2026-06-11T00:00:00.000Z","status":"report-only（未 APPLY；裁決權在使用者）","method":"主對話親讀核心層（auto-load 5 源 + 17 refs + pilot 三件套 + harness-meta + memory 全檔）+ 2× researcher fan-out（autoresearch 系 / domain skills）；所有引用發現經主對話 grep/diff 機械重驗","scope":"CLAUDE.md · .claude/rules/** · .claude/refs/** · .claude/skills/** · .claude/agents/** · .claude/commands/** · memory/**","session-model":"claude-fable-5（settings.json baseline = claude-sonnet-4-6 → 模型世代 drift 為本稽核核心發現之一）","type":"audit"},"headers":[],"relativePath":"research/reports/archive/2026-06-11-instruction-files-self-audit.md","filePath":"research/reports/archive/2026-06-11-instruction-files-self-audit.md","lastUpdated":1785909234000}'),r={name:"research/reports/archive/2026-06-11-instruction-files-self-audit.md"};function s(i,e,c,n,l,m){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="instruction-files-全量自我稽核報告" tabindex="-1">Instruction Files 全量自我稽核報告 <a class="header-anchor" href="#instruction-files-全量自我稽核報告" aria-label="Permalink to &quot;Instruction Files 全量自我稽核報告&quot;">​</a></h1><blockquote><p><strong>TLDR</strong>：最大問題不是單條規則錯，而是三件事：① 存在<strong>兩套同名但順序相反的六階段 Loop</strong>，14+ 個檔案跟錯邊；② 整個模型層（pilot 三件套、定價、escalation ladder、&quot;Opus is the ceiling&quot;）已因 Fable 5 世代而過期，而 <code>prompt-lifecycle.md</code> 自己早已預言此事（「換模型後 auto-load 規則須重評，不可累加沿用」）；③ 多份文件<strong>以壞示範教學</strong>——byte 量測規範漏掉實際載入的檔案、preach Rule of 3 的庫存著 byte-identical 重複檔。</p><p><strong>稽核過程佐證</strong>：兩個 researcher sub-agent 回報 <code>prompt-lifecycle.md</code> 與 <code>harness-meta-GOTCHAS.md</code> 為「死檔案」，經主對話親驗均存在（後者為 core.md 路徑寫法誤導）——<code>unverified_success</code> 閘門對最強模型仍 load-bearing 的現場證明。</p></blockquote><hr><h2 id="_1-互相矛盾-雙方原文" tabindex="-1">1. 互相矛盾（雙方原文） <a class="header-anchor" href="#_1-互相矛盾-雙方原文" aria-label="Permalink to &quot;1. 互相矛盾（雙方原文）&quot;">​</a></h2><h3 id="_1a-兩套-canonical-loop-test-apply-順序相反-最嚴重的結構矛盾" tabindex="-1">1a. 兩套 canonical Loop，TEST/APPLY 順序相反（最嚴重的結構矛盾） <a class="header-anchor" href="#_1a-兩套-canonical-loop-test-apply-順序相反-最嚴重的結構矛盾" aria-label="Permalink to &quot;1a. 兩套 canonical Loop，TEST/APPLY 順序相反（最嚴重的結構矛盾）&quot;">​</a></h3><ul><li><code>CLAUDE.md:8</code> / <code>core.md:19</code>：「<strong>OBSERVE→IDENTIFY→PROPOSE→APPLY→TEST→RECORD</strong>」（先改後測）</li><li><code>refs/harness-loop.md:14</code>（自稱「本檔為 workspace <strong>唯一 canonical</strong> loop 定義」）：表格順序 OBSERVE→IDENTIFY→PROPOSE→<strong>TEST→APPLY</strong>→RECORD（「TEST｜Apply 前預檢」）</li><li>跟隨後者：<code>pilot-shared-preflights.md:126</code>、<code>eval-designer/SKILL.md:136</code>、<strong>14+ 個 SKILL 自我進化表</strong>（<code>sre/SKILL.md:328</code>、<code>finops/SKILL.md:252</code>、<code>review-hub/SKILL.md:189</code> 等，全寫「遵循 OBSERVE→IDENTIFY→PROPOSE→TEST→APPLY→RECORD 閉環」）</li></ul><p>兩順序各自說得通（寫 code 先 APPLY 再 TEST；改 harness 先 TEST 提案再 APPLY），但同名六階段、兩檔各自宣稱 canonical（<code>karpathy-mnilax-best-solution.md:5</code>「本檔 = canonical」 vs <code>harness-loop.md</code>「唯一 canonical」）；且 CLAUDE.md 說「改進/稽核任務走此六階段」用 APPLY→TEST 順序，而真正的改進 loop（harness-loop）卻是 TEST→APPLY。</p><h3 id="_1b-token-budget-同組數字一邊「硬性」一邊「soft」-且與自身-compact-閾值矛盾" tabindex="-1">1b. Token budget：同組數字一邊「硬性」一邊「Soft」，且與自身 compact 閾值矛盾 <a class="header-anchor" href="#_1b-token-budget-同組數字一邊「硬性」一邊「soft」-且與自身-compact-閾值矛盾" aria-label="Permalink to &quot;1b. Token budget：同組數字一邊「硬性」一邊「Soft」，且與自身 compact 閾值矛盾&quot;">​</a></h3><ul><li><code>context-management.md:18</code>：「<strong>硬性 Token Budget</strong>…Per-task: <strong>4,000</strong> tokens…Per-session: <strong>30,000</strong> tokens」</li><li><code>karpathy-mnilax-best-solution.md:200</code>（同數字出處）：「Token 預算管理（<strong>Soft Token Budget</strong>）」</li><li>同檔自我矛盾：compact 閾值「一般任務 <strong>70%</strong>」——70% × 200K = 140K，遠超 30K session 上限；兩規則不可能同時有意義</li><li><code>autoresearch/SKILL.md:67</code>：「Low &lt; 50K；Medium 50-200K；High 200K+…最壞 500K+ per run」——內建 skill 的最低檔位即超 session 預算 1.7×，且從不引用該預算</li></ul><h3 id="_1c-mid-session-換模型-一邊禁止、一邊指示" tabindex="-1">1c. Mid-session 換模型：一邊禁止、一邊指示 <a class="header-anchor" href="#_1c-mid-session-換模型-一邊禁止、一邊指示" aria-label="Permalink to &quot;1c. Mid-session 換模型：一邊禁止、一邊指示&quot;">​</a></h3><ul><li><code>context-management.md:7</code>：「<strong>Mid-session 禁止</strong>：① 切換模型」；<code>prompt-caching-rules.md:76</code>：「切換 model（haiku → sonnet）= cache 全部失效；mode 切換為 session 結束後動作」</li><li><code>haiku-pilot/SKILL.md:173-178</code>：「<strong>Escalate to Sonnet 4.6</strong>: Same problem failed ≥ 3 times…」+ 診斷流程圖「Still fails (3rd attempt) → Escalate to Sonnet」</li></ul><p>escalation gate 字面語義即 mid-session 換模型。可用 sub-agent model override 化解，但兩處文字均未說明橋接，照字面執行必違反其一。</p><h3 id="_1d-auto-load-byte-上限-18-000-vs-19-000-13-000-是否硬牆兩個-gotcha-互打" tabindex="-1">1d. Auto-load byte 上限：18,000 vs 19,000；13,000 是否硬牆兩個 GOTCHA 互打 <a class="header-anchor" href="#_1d-auto-load-byte-上限-18-000-vs-19-000-13-000-是否硬牆兩個-gotcha-互打" aria-label="Permalink to &quot;1d. Auto-load byte 上限：18,000 vs 19,000；13,000 是否硬牆兩個 GOTCHA 互打&quot;">​</a></h3><ul><li><code>core.md:75</code> / <code>rules/README.md:3</code>：「完整區間至 <strong>19,000</strong> 上限」</li><li><code>token-waste-audit/SKILL.md:64</code>：「auto-load &gt; <strong>18,000</strong> bytes（canon 區間上限）→ RTK 風險高」——18.5K workspace 被稽核工具標 HIGH、被 canonical 規則視為合格</li><li><code>overnight-research/GOTCHAS.md:16</code>：「加表格…超過 <strong>13KB 上限</strong>」（當硬牆寫）vs <code>autoload-evolution/GOTCHAS.md:7</code>：「13,000 是<strong>軟性目標非硬截斷牆</strong>…16,716 bytes 完整載入無截斷」</li></ul><h3 id="_1e-security-路由三角矛盾" tabindex="-1">1e. Security 路由三角矛盾 <a class="header-anchor" href="#_1e-security-路由三角矛盾" aria-label="Permalink to &quot;1e. Security 路由三角矛盾&quot;">​</a></h3><ul><li><code>agents/security-auditor.md:102</code>：「Invoke via: <code>/ship-review</code>…or <strong><code>/security-compliance</code> for full OWASP/STRIDE</strong>」</li><li><code>security-compliance/SKILL.md:3</code>：「<strong>Do NOT use for: application security review（→ autoresearch:security）</strong>」——A 導向 B，B 明拒並導向 C</li><li>另一組：<code>agents/quick-code-reviewer.md:3</code>「security audit (use <strong>security-reviewer</strong>)」 vs <code>agents/security-reviewer.md:3</code>「Do NOT use for: OWASP…（use <strong>security-auditor</strong>）」 vs <code>ship-review/SKILL.md:30</code> fan-out 給 security-auditor</li></ul><h3 id="_1f-pilot-檔內-修正後數字與殘留舊數字並存" tabindex="-1">1f. Pilot 檔內：修正後數字與殘留舊數字並存 <a class="header-anchor" href="#_1f-pilot-檔內-修正後數字與殘留舊數字並存" aria-label="Permalink to &quot;1f. Pilot 檔內：修正後數字與殘留舊數字並存&quot;">​</a></h3><ul><li><code>sonnet-pilot/SKILL.md:31</code>：「Cost ratio: Sonnet ($3/$15) vs <strong>Opus ($15/$75)</strong>」——同檔 <code>:261</code> 自標 🔴 的「誤用定價」（實際 Opus 4.8 = $5/$25），開頭未改</li><li><code>sonnet-pilot/SKILL.md:288</code> Verification：「<strong>55–65% savings?</strong>」 vs <code>:265</code>「Conservative estimate: <strong>30–35%</strong>」</li><li><code>opus-pilot/SKILL.md:337</code>：「<strong>60–75% cost reduction</strong>」 vs <code>:310</code>「<strong>−20–35% cost</strong>…（舊『−60–75%』基於誤用的 $15/$75）」</li><li><code>haiku-pilot/SKILL.md:13</code>「節費 <strong>70-85%</strong>」+ <code>:261</code>「Actually saving <strong>70–85%</strong>?」 vs <code>:233</code>「~70%（非 87%）」</li></ul><h3 id="_1g-其他已驗證矛盾" tabindex="-1">1g. 其他已驗證矛盾 <a class="header-anchor" href="#_1g-其他已驗證矛盾" aria-label="Permalink to &quot;1g. 其他已驗證矛盾&quot;">​</a></h3><ul><li><code>research-hub/SKILL.md:7</code> frontmatter 含 <code>Write</code> vs <code>:357</code>「本 skill allowed-tools <strong>不含</strong> Write」</li><li><code>subagent-strategy.md</code>「child 不 self-retry」 vs <code>autoresearch/SKILL.md:160</code>「CRASHED → Fix (<strong>max 3 attempts</strong>)」</li><li><code>skill-evolution</code> rubric 硬限 350 行 vs 其 GOTCHAS 引用的 500 行規範（出處 <code>skill-authoring.md</code> <strong>不存在</strong>）</li><li><code>commands/memory-compactor.md:11,22</code> 操作根目錄 <code>MEMORY.md</code> vs <code>core.md:87</code> canonical 路徑 <code>memory/MEMORY.md</code>（根目錄該檔已不存在）</li></ul><hr><h2 id="_2-為更弱模型而存在的規則" tabindex="-1">2. 為更弱模型而存在的規則 <a class="header-anchor" href="#_2-為更弱模型而存在的規則" aria-label="Permalink to &quot;2. 為更弱模型而存在的規則&quot;">​</a></h2><h3 id="_2a-模型世代整體-drift-最大宗" tabindex="-1">2a. 模型世代整體 drift（最大宗） <a class="header-anchor" href="#_2a-模型世代整體-drift-最大宗" aria-label="Permalink to &quot;2a. 模型世代整體 drift（最大宗）&quot;">​</a></h3><p>本 session 跑 <code>claude-fable-5</code>；<code>settings.json</code> = <code>claude-sonnet-4-6</code>，<code>harness-model-fit.json</code> baseline 同。</p><table tabindex="0"><thead><tr><th>位置</th><th>內容</th><th>狀態</th></tr></thead><tbody><tr><td><code>CLAUDE.md:24</code></td><td>「預設 Sonnet 4.6」+ 三 pilot 模式</td><td>模型網格無 Fable</td></tr><tr><td><code>opus-pilot/SKILL.md:212,301</code></td><td>「<strong>Opus is the ceiling</strong>. There is no auto-upgrade」「<strong>No upward escalation exists</strong>」</td><td>事實已錯：Fable 5 在 Opus 之上</td></tr><tr><td><code>refs/model-selection-grid.md</code></td><td>Haiku 4.5/Sonnet 4.6/Opus 4.8 路由 + trial-001 表（<code>:44</code> <strong>自註</strong>「該檔不存在於 repo → 數字不可驗證」卻保留）</td><td>漂移 + 自承不可驗證</td></tr><tr><td><code>refs/pilot-shared-preflights.md:85-99</code></td><td>CLI v2.1.158 flag 驗證、定價矩陣、「Opus 4.8 tokenizer 多耗 ~35%」</td><td>版本 pin 時效快照</td></tr><tr><td><code>memory/MEMORY.md:109</code></td><td>待整合洞察 #4「@Mnilax 7.30：<strong>Fable 5</strong> silent fallback…→ CLAUDE.md」</td><td>workspace 自己已記錄、尚未整合</td></tr></tbody></table><p>裁決依據已內建：<code>prompt-lifecycle.md:19</code>「跨模型沿用 prompt 最壞 −10.77pp → <strong>換模型後 auto-load 規則須重評，不可累加沿用</strong>」。按此規則，pilot 三件套（~62KB）整批到期。</p><h3 id="_2b-為弱模型行為建模的補丁層" tabindex="-1">2b. 為弱模型行為建模的補丁層 <a class="header-anchor" href="#_2b-為弱模型行為建模的補丁層" aria-label="Permalink to &quot;2b. 為弱模型行為建模的補丁層&quot;">​</a></h3><ul><li><code>core.md</code> OBSERVE：「讀取 <strong>&gt; 200 行</strong>檔 → limit/offset 分段，每段報 N-M/X 行」+「<strong>不得假設截斷後為空</strong>」——Read 工具預設讀 2000 行；皆為舊弱模型失敗模式</li><li><code>haiku-pilot/SKILL.md:61-67</code> Citation Anchor 密度配額（hard task ≥5 錨點/段）——為 Haiku 編造率 25% 設計的機械代理指標；<code>sonnet-pilot:117-121</code> <code>:LineN</code> 行號錨點同理</li><li>各 escalation ladder（「同一問題失敗 ≥3 次 → 升 Sonnet」「3 Haiku failures ≠ Opus needed」）——以舊模型階梯為前提</li><li><code>sonnet-pilot/SKILL.md:24-25</code> <strong>自承</strong>：「Sonnet + SKILL = 283/300; Sonnet Plain = 283/300…<strong>SKILL net gain on routine extraction = 0</strong>」</li><li><code>context-management.md:21</code>「初學者 ~60%」——使用者為 10+ 年 SRE</li><li>UserPromptSubmit hook 每 prompt 注入「先用 1-2 句複述你的理解」——對自然顯露假設的模型是 token 稅</li></ul><h3 id="_2c-漂移的硬編碼事實" tabindex="-1">2c. 漂移的硬編碼事實 <a class="header-anchor" href="#_2c-漂移的硬編碼事實" aria-label="Permalink to &quot;2c. 漂移的硬編碼事實&quot;">​</a></h3><ul><li><code>commands/quick-commit.md:22</code> <code>Co-Authored-By: Claude Sonnet 4.6</code></li><li><code>overnight-research/references/phases.md:97</code> 搜尋詞硬編碼「<strong>2024 OR 2025</strong>」（系統性漏 2026 來源）</li><li><code>skill-evolution/SKILL.md:180</code> 硬編碼過去分支 <code>git push -u origin claude/kind-ritchie-9LFRp</code></li><li><code>sia/REFERENCE.md:44-46</code> 模型 ID 展開（<code>claude-opus-4-8</code> 等）；<code>:31</code> openhands 預設 <code>gemini-3.1-pro-preview</code></li><li><code>REFERENCES.md:43</code> 引「Opus <strong>4.7</strong> Best Practices」blog</li><li><code>commands/quick-pr.md:14,31,46</code> 全程用 <code>gh</code> 而遠端 session 無 <code>gh</code>（<code>verified-merge/SKILL.md:35</code> 有 fallback 註記，quick-pr 無）</li></ul><h3 id="_2d-死指針-誤導路徑-全部親驗" tabindex="-1">2d. 死指針 / 誤導路徑（全部親驗） <a class="header-anchor" href="#_2d-死指針-誤導路徑-全部親驗" aria-label="Permalink to &quot;2d. 死指針 / 誤導路徑（全部親驗）&quot;">​</a></h3><ul><li><code>refs/harness-design.md:128,226,234</code> 三處引「<strong>45% 規則（subagent-strategy.md）</strong>」——該規則已不在 subagent-strategy.md</li><li><code>core.md</code> TEST 段「全文見 <code>refs/harness-meta</code> GOTCHAS」——檔案實在 <code>.claude/skills/harness-meta/references/harness-meta-GOTCHAS.md</code>，<code>refs/</code> 查無（路徑誤導，非死檔）</li><li><code>prompt-lifecycle.md:44</code> 引 <code>scripts/measure-cache.sh</code>（不存在）</li><li><code>harness-meta/SKILL.md:89</code> 引 <code>scripts/schema-verify.sh</code>（不存在）</li><li><code>autoresearch:wiki</code> 列於 SKILL 路由表但 <code>commands/autoresearch/wiki.md</code> 不存在</li><li><code>memory/README.md:27-31</code> 描述的根層 <code>MEMORY.md</code>（L2 層）已不存在</li><li><code>ship-review/SKILL.md:91</code> 引 <code>2026-05-15-vesper</code> 查無對應歸檔檔名</li><li><code>skill-evolution/GOTCHAS.md:7,9</code> 三引 <code>skill-authoring.md</code>（不存在）</li></ul><hr><h2 id="_3-以壞示範教學-違反自己宣講的-pattern" tabindex="-1">3. 以壞示範教學（違反自己宣講的 pattern） <a class="header-anchor" href="#_3-以壞示範教學-違反自己宣講的-pattern" aria-label="Permalink to &quot;3. 以壞示範教學（違反自己宣講的 pattern）&quot;">​</a></h2><h3 id="_3a-byte-量測規範保證量錯" tabindex="-1">3a. Byte 量測規範保證量錯 <a class="header-anchor" href="#_3a-byte-量測規範保證量錯" aria-label="Permalink to &quot;3a. Byte 量測規範保證量錯&quot;">​</a></h3><p>canonical 5 源實測 <code>wc -c</code> = <strong>18,984 / 19,000</strong>（餘 16 bytes）。但實際 auto-load <strong>還包含 <code>rules/INDEX.md</code>（1,584 bytes）</strong>——本 session context 親證載入。實際 ≈ <strong>20,568 bytes，已超 19,000 上限</strong>。<code>MEMORY.md</code> Lesson 2026-06-05-F 教「canonical 5 源固定列舉…勿用 glob」——這條 Lesson 把量測鎖死在漏掉真實載入檔的狀態。preach「先量測再改」的體系，量測器本身對不上現實。</p><h3 id="_3b-「可推導資訊-噪音」的規則庫充滿可推導重複" tabindex="-1">3b. 「可推導資訊 = 噪音」的規則庫充滿可推導重複 <a class="header-anchor" href="#_3b-「可推導資訊-噪音」的規則庫充滿可推導重複" aria-label="Permalink to &quot;3b. 「可推導資訊 = 噪音」的規則庫充滿可推導重複&quot;">​</a></h3><p><code>core.md</code> APPLY：「<strong>只寫無法從 repo 推導的行為契約</strong>」。然而：同一份 8 列自我進化表逐字複製 <strong>14+ 份</strong> SKILL；GOTCHA footer 逐字複製 <strong>20 份</strong>；agent dispatch 表在 <code>subagent-strategy.md</code> / <code>AGENTS.md §2</code> / <code>trigger-index.md</code> / <code>RESOLVER.md</code> / 各 pilot router <strong>五處平行維護</strong>；<code>AGENTS.md §6b</code> 27 skill 清單可由 <code>ls .claude/skills/</code> 推導。</p><h3 id="_3c-rule-of-3-的守護者庫存-byte-identical-複本" tabindex="-1">3c. Rule of 3 的守護者庫存 byte-identical 複本 <a class="header-anchor" href="#_3c-rule-of-3-的守護者庫存-byte-identical-複本" aria-label="Permalink to &quot;3c. Rule of 3 的守護者庫存 byte-identical 複本&quot;">​</a></h3><p><code>diff -q</code> 實證：<code>security-compliance/references/deploy-and-naming.md</code> ≡ <code>sre/references/cathaysec-terraform-deploy-and-naming.md</code>、<code>module-examples.md</code> ≡ <code>cathaysec-terraform-module-examples.md</code>（完全相同）；<code>gcp-modules.md</code> 兩份 12KB 僅差 4 行。</p><h3 id="_3d-「重寫該段-不要-ship-標籤」vs-修正以註記疊加" tabindex="-1">3d. 「重寫該段，不要 ship 標籤」vs 修正以註記疊加 <a class="header-anchor" href="#_3d-「重寫該段-不要-ship-標籤」vs-修正以註記疊加" aria-label="Permalink to &quot;3d. 「重寫該段，不要 ship 標籤」vs 修正以註記疊加&quot;">​</a></h3><p><code>pilot-shared-preflights.md §B</code>：「任何 grep 失敗 → <strong>重寫該段</strong>，不要 ship <code>[unverified]</code> 標籤作為 workaround」。三本 pilot 對定價錯誤的處理卻是保留錯誤數字 + 疊 🔴 修正註記（每檔 2-3 處），sonnet-pilot 開頭 $15/$75 甚至漏改。</p><h3 id="_3e-eval-designer-自知違規、記錄了、沒修" tabindex="-1">3e. eval-designer 自知違規、記錄了、沒修 <a class="header-anchor" href="#_3e-eval-designer-自知違規、記錄了、沒修" aria-label="Permalink to &quot;3e. eval-designer 自知違規、記錄了、沒修&quot;">​</a></h3><p><code>eval-designer/GOTCHAS.md:16</code>：「Phase 2 Checkbox 為 <strong>LLM 判斷非機械驗證</strong>…<strong>違反 R4</strong>」——GOTCHA 入庫，SKILL.md Phase 2 原樣未動；恰為 harness-meta 自己禁止的「只記錄不升格」。</p><h3 id="_3f-memory-md-違反自家格式規範" tabindex="-1">3f. MEMORY.md 違反自家格式規範 <a class="header-anchor" href="#_3f-memory-md-違反自家格式規範" aria-label="Permalink to &quot;3f. MEMORY.md 違反自家格式規範&quot;">​</a></h3><p><code>core.md</code>：「≤5 決策…<strong>≤30 行/節</strong>」。實況：<code>memory/MEMORY.md:153-171</code> 殘留未展開的 shell heredoc <code>$(cat &lt;&lt;&#39;EOF&#39;)…EOF )</code>（hook 把 PR body 模板原樣貼入）；多節為整段 PR body 含表格；202 行已超 200 上限。</p><h3 id="_3g-output-discipline-≤150-字與-the-loop-輸出儀式結構性互斥" tabindex="-1">3g. output-discipline ≤150 字與 The Loop 輸出儀式結構性互斥 <a class="header-anchor" href="#_3g-output-discipline-≤150-字與-the-loop-輸出儀式結構性互斥" aria-label="Permalink to &quot;3g. output-discipline ≤150 字與 The Loop 輸出儀式結構性互斥&quot;">​</a></h3><p>「純文字回答 ≤ 150 字」vs core.md 同時要求：詮釋 ≤2 句＋假設＋選項（IDENTIFY）＋前 5 後 5 行輸出（TEST）＋checkpoint（RECORD）。例外清單救了多步驟任務，但單步實作任務照規執行即超標。</p><hr><h2 id="_4-刪除-保留建議-待使用者裁決" tabindex="-1">4. 刪除 / 保留建議（待使用者裁決） <a class="header-anchor" href="#_4-刪除-保留建議-待使用者裁決" aria-label="Permalink to &quot;4. 刪除 / 保留建議（待使用者裁決）&quot;">​</a></h2><h3 id="刪-或凍結歸檔" tabindex="-1">刪（或凍結歸檔） <a class="header-anchor" href="#刪-或凍結歸檔" aria-label="Permalink to &quot;刪（或凍結歸檔）&quot;">​</a></h3><ol><li><strong>pilot 三件套 + preflights §C/§E 定價層</strong>（~62KB）——為上一世代模型行為建模；sonnet-pilot 自證 routine 增益 = 0；定價已錯過一輪；escalation 前提（Opus = ceiling）不成立。保留模式概念可重寫為 model-agnostic 一頁。</li><li><strong>model-selection-grid.md trial-001 表</strong>——自承來源不存在、與後續 baseline 部分矛盾。</li><li><strong>14× 自我進化表 + 20× GOTCHA footer</strong> → 各換一行指針到 <code>skill-gotcha-protocol.md</code>。</li><li><strong>security-compliance / sre 重複 reference 檔</strong>——留一份、另一處指針。</li><li><strong>AGENTS.md §6b skill 清單、trigger-index 與 RESOLVER 重疊部分</strong>——可推導即噪音。</li><li><strong>pilot 檔內所有 🔴 修正註記</strong>——直接寫對的數字，舊數字留 git 歷史。</li><li><strong><code>overnight-research/GOTCHAS.md:16</code> 13K 硬牆條目</strong>——已被自家實證反推翻。</li><li><strong>死指針</strong>：harness-design 45% 規則引用、measure-cache.sh、schema-verify.sh、memory/README 根層 MEMORY.md L2 描述。</li></ol><h3 id="原樣留-理由" tabindex="-1">原樣留（理由） <a class="header-anchor" href="#原樣留-理由" aria-label="Permalink to &quot;原樣留（理由）&quot;">​</a></h3><ol><li><strong>core.md 不可逆動作 gate、生產紅線、git 流程、No-Commit 紅線</strong>——防「後果不可逆」，與模型強度無關；模型越強動作越快，gate 越 load-bearing。</li><li><strong><code>unverified_success</code> 閘門 + 「subagent verdict 非證據」全套</strong>——本稽核中 researcher 誤報兩個「死檔案」被主對話親驗推翻；<code>harness-meta-GOTCHAS.md:141</code> 論文結論方向正確（越強的模型需要越強的驗證 harness）。<strong>換更強模型該刪的是行為補丁，該留的是驗證閘門。</strong></li><li><strong>error-handling.md 確定性重試表 / stop_reason 對照</strong>——「判斷 vs 決定」的正確落地。</li><li><strong>prompt-caching-rules、cache-health-metrics 機制事實</strong>——平台機制，弱模型無關（門檻表需隨新模型補列）。</li><li><strong>語言規則（台灣繁中＋compact 後維持）</strong>——使用者偏好，有實際漂移 Lesson（2026-05-29e）背書。</li><li><strong>MEMORY/RATCHET/Lesson 機制本身</strong>——compounding engineering 是真正在運轉的部分；該修的是 hook 貼 PR body 的衛生，不是機制。</li><li><strong>prompt-lifecycle.md</strong>——唯一預見本次稽核的規則（「換模型後仍最佳？」）；該升格，不該動。</li></ol><h3 id="最優先三刀" tabindex="-1">最優先三刀 <a class="header-anchor" href="#最優先三刀" aria-label="Permalink to &quot;最優先三刀&quot;">​</a></h3><p>① 統一兩套 Loop 順序並指定唯一 canonical；② byte 量測對齊實際載入集（含 rules/README.md）；③ 處置 pilot 三件套。</p><hr><h2 id="附錄-稽核方法與信度" tabindex="-1">附錄：稽核方法與信度 <a class="header-anchor" href="#附錄-稽核方法與信度" aria-label="Permalink to &quot;附錄：稽核方法與信度&quot;">​</a></h2><ul><li><strong>主對話親讀</strong>：auto-load 5 源（context 內建）、17 refs 全檔、pilot 三 SKILL、harness-meta SKILL + GOTCHAS、memory 全檔、AGENTS.md。</li><li><strong>Fan-out</strong>：2× researcher（autoresearch 系 + domain skills/agents/commands），其結論經主對話 grep/diff 逐項重驗後才採信。</li><li><strong>被推翻的 sub-agent 宣稱</strong>（記錄為 unverified_success 範例）：① 「<code>prompt-lifecycle.md</code> 不存在」——主對話已親讀全文；② 「<code>harness-meta-GOTCHAS.md</code> 零檔案」——實存於 <code>.claude/skills/harness-meta/references/</code>，僅 core.md 路徑寫法誤導。</li><li>本報告為 OBSERVE→IDENTIFY 產出；PROPOSE 僅列建議、未 APPLY。</li></ul>',59)])])}const g=o(r,[["render",s]]);export{u as __pageData,g as default};
